def chemin_grille_td(m, n):
    cache = {}

    def aux(i, j):
        if (i, j) in cache:
            return cache[(i, j)]
        if i == 0 or j == 0:
            resultat = 1
        else:
            resultat = aux(i - 1, j) + aux(i, j - 1)
        cache[(i, j)] = resultat
        return resultat

    return aux(m - 1, n - 1)

def rendu_td(montant, pieces):
    cache = {}

    def aux(m):
        if m == 0:
            return 0
        if m in cache:
            return cache[m]

        meilleur = None
        for p in pieces:
            if p <= m:
                sous_resultat = aux(m - p)
                if sous_resultat is not None:
                    candidat = sous_resultat + 1
                    if meilleur is None or candidat < meilleur:
                        meilleur = candidat

        cache[m] = meilleur
        return meilleur

    resultat = aux(montant)
    if resultat is not None:
        return resultat
    else:
        return -1

def rendu_bu(montant, pieces):
    INFINI = float('inf')
    # table[m] contiendra le nombre minimal de pièces pour rendre m
    table = [0] + [INFINI] * montant

    for m in range(1, montant + 1):
        for p in pieces:
            if p <= m and table[m - p] + 1 < table[m]:
                # Utiliser cette pièce donne un résultat meilleur que ce
                # qu'on avait trouvé jusqu'ici pour ce montant m
                table[m] = table[m - p] + 1

    # Si table[montant] est resté à l'infini, aucune combinaison de pièces
    # ne permet de l'atteindre exactement
    if table[montant] != INFINI:
        return table[montant]
    else:
        return -1

def sac_a_dos_td(objets, capacite):
    cache = {}

    def aux(i, capacite_restante):
        if i == len(objets) or capacite_restante == 0:
            return 0
        if (i, capacite_restante) in cache:
            return cache[(i, capacite_restante)]

        poids, valeur = objets[i]

        meilleur = aux(i + 1, capacite_restante)
        if poids <= capacite_restante:
            avec_objet = valeur + aux(i + 1, capacite_restante - poids)
            if avec_objet > meilleur:
                meilleur = avec_objet

        cache[(i, capacite_restante)] = meilleur
        return meilleur

    return aux(0, capacite)

def minimax_nim(n, maximise):
    # Cas de base : il ne reste plus d'allumette à prendre. Le joueur dont
    # c'est le tour ne peut donc pas jouer : c'est l'ADVERSAIRE qui vient de
    # prendre la dernière allumette au coup précédent, et qui a donc gagné.
    if n == 0:
        # Si c'est le tour de A (maximise) mais qu'il ne peut pas jouer,
        # c'est B qui a gagné : la valeur (du point de vue de A) est -1.
        # Si c'est le tour de B, c'est A qui a gagné : la valeur est +1.
        if maximise:
            return -1
        else:
            return 1

    if maximise:
        # Le joueur A cherche à MAXIMISER la valeur : on essaie chaque coup
        # possible (retirer 1, 2 ou 3 allumettes, sans dépasser n), et on
        # garde la meilleure valeur trouvée parmi tous les coups
        meilleure_valeur = -2  # plus petit que toute valeur possible (-1 au minimum)
        for coup in (1, 2, 3):
            if coup <= n:
                # Après ce coup, c'est au tour de B (maximise devient False)
                valeur = minimax_nim(n - coup, False)
                if valeur > meilleure_valeur:
                    meilleure_valeur = valeur
        return meilleure_valeur
    else:
        # Le joueur B cherche à MINIMISER la valeur (du point de vue de A) :
        # on garde cette fois la PIRE valeur trouvée parmi tous les coups
        pire_valeur = 2  # plus grand que toute valeur possible (1 au maximum)
        for coup in (1, 2, 3):
            if coup <= n:
                # Après ce coup, c'est au tour de A (maximise devient True)
                valeur = minimax_nim(n - coup, True)
                if valeur < pire_valeur:
                    pire_valeur = valeur
        return pire_valeur

