def meilleur_coup_minimax_profondeur(n, profondeur):
    # Minimax classique (comme dans le premier exercice), mais avec DEUX
    # cas de base au lieu d'un seul : la vraie fin de partie (n == 0, valeur
    # exacte) et l'arrêt anticipé faute de profondeur (valeur estimée)
    def score(n, maximise, profondeur):
        if n == 0:
            # Fin de partie réelle : valeur exacte, garantie correcte
            if maximise:
                return VALEUR_DEFAITE
            else:
                return VALEUR_VICTOIRE
        if profondeur == 0:
            # On s'arrête là : on renvoie une ESTIMATION plutôt que la vraie
            # valeur. evaluation_nim(n) est exprimée du point de vue du joueur
            # au trait : si ce joueur est A (maximise), on la garde telle
            # quelle ; si c'est B, on l'inverse pour revenir au point de vue
            # de A — exactement comme pour VALEUR_VICTOIRE/VALEUR_DEFAITE
            # juste au-dessus
            if maximise:
                return evaluation_nim(n)
            else:
                return -evaluation_nim(n)
        if maximise:
            meilleure_valeur = float('-inf')
            for coup in (1, 2, 3):
                if coup <= n:
                    valeur = score(n - coup, False, profondeur - 1)
                    if valeur > meilleure_valeur:
                        meilleure_valeur = valeur
            return meilleure_valeur
        else:
            pire_valeur = float('inf')
            for coup in (1, 2, 3):
                if coup <= n:
                    valeur = score(n - coup, True, profondeur - 1)
                    if valeur < pire_valeur:
                        pire_valeur = valeur
            return pire_valeur

    # Au tout premier coup, c'est à A de jouer : on essaie chaque coup et on
    # garde celui qui donne la meilleure valeur (du point de vue de A)
    meilleur_coup = None
    meilleure_valeur = float('-inf')
    for coup in (1, 2, 3):
        if coup <= n:
            valeur = score(n - coup, False, profondeur - 1)
            if valeur > meilleure_valeur:
                meilleure_valeur = valeur
                meilleur_coup = coup
    return meilleur_coup

